import json

f1 = '/root/autodl-tmp/recovery_aware_struct_prune/results/humaneval_grpo_cka_only_20_2048.json'
f2 = '/root/autodl-tmp/recovery_aware_struct_prune/results/humaneval_grpo_rasp_20_fair_2048.json'
d1 = json.load(open(f1))
d2 = json.load(open(f2))

ex1 = {e['task_id']: e for e in d1['examples']}
ex2 = {e['task_id']: e for e in d2['examples']}

def classify_error(e):
    if e['passed']:
        return 'passed'
    err = e.get('error', '') or ''
    if 'SyntaxError' in err:
        # Check if it looks like reasoning text in code
        if any(kw in err.lower() for kw in ['i need to', 'let me', 'i think', 'first', 'okay', 'the function', 'we need']):
            return 'reasoning_as_code'
        return 'syntax_error'
    elif 'AssertionError' in err or 'AssertError' in err:
        return 'logic_error'
    elif 'TypeError' in err:
        return 'type_error'
    elif 'NameError' in err:
        return 'name_error'
    elif 'IndexError' in err:
        return 'index_error'
    elif 'TimeoutError' in err or 'timeout' in err.lower():
        return 'timeout'
    elif e['response_length'] >= 2048:
        return 'max_length_hit'
    else:
        return 'other_runtime'

# Classify all failures
print('=== CKA-only failure patterns ===')
cka_fail_patterns = {}
for tid in sorted(ex1.keys()):
    if not ex1[tid]['passed']:
        p = classify_error(ex1[tid])
        cka_fail_patterns.setdefault(p, []).append(tid)

for p, tids in sorted(cka_fail_patterns.items(), key=lambda x: -len(x[1])):
    print(f'  {p}: {len(tids)}')

print()
print('=== RASP-fair failure patterns ===')
rasp_fail_patterns = {}
for tid in sorted(ex2.keys()):
    if not ex2[tid]['passed']:
        p = classify_error(ex2[tid])
        rasp_fail_patterns.setdefault(p, []).append(tid)

for p, tids in sorted(rasp_fail_patterns.items(), key=lambda x: -len(x[1])):
    print(f'  {p}: {len(tids)}')

# Response length distribution for failures
print()
print('=== Response length stats (failures only) ===')
cka_lens = [ex1[tid]['response_length'] for tid in ex1 if not ex1[tid]['passed']]
rasp_lens = [ex2[tid]['response_length'] for tid in ex2 if not ex2[tid]['passed']]
import statistics
print(f'CKA fails: mean={statistics.mean(cka_lens):.0f}, median={statistics.median(cka_lens):.0f}, max_len_count={sum(1 for l in cka_lens if l>=2048)}')
print(f'RASP fails: mean={statistics.mean(rasp_lens):.0f}, median={statistics.median(rasp_lens):.0f}, max_len_count={sum(1 for l in rasp_lens if l>=2048)}')

# CKA-only pass: what does RASP fail with?
print()
print('=== CKA pass, RASP fail: RASP failure patterns ===')
cka_only_pass = [tid for tid in ex1 if ex1[tid]['passed'] and not ex2[tid]['passed']]
rasp_fail_in_cka_pass = {}
for tid in cka_only_pass:
    p = classify_error(ex2[tid])
    rasp_fail_in_cka_pass.setdefault(p, []).append(tid)
for p, tids in sorted(rasp_fail_in_cka_pass.items(), key=lambda x: -len(x[1])):
    print(f'  {p}: {len(tids)} -> {tids[:3]}')

# RASP-only pass: what does CKA fail with?
print()
print('=== RASP pass, CKA fail: CKA failure patterns ===')
rasp_only_pass = [tid for tid in ex1 if not ex1[tid]['passed'] and ex2[tid]['passed']]
cka_fail_in_rasp_pass = {}
for tid in rasp_only_pass:
    p = classify_error(ex1[tid])
    cka_fail_in_rasp_pass.setdefault(p, []).append(tid)
for p, tids in sorted(cka_fail_in_rasp_pass.items(), key=lambda x: -len(x[1])):
    print(f'  {p}: {len(tids)} -> {tids[:3]}')
"
